"use client"

import { useEffect, useState } from "react"
import { Download, TrendingUp, TrendingDown, Wallet, Users, Printer } from "lucide-react"
import { Bar, BarChart, CartesianGrid, Legend, ResponsiveContainer, Tooltip, XAxis, YAxis } from "recharts"
import { PageShell, Stat, Empty } from "@/components/accounting/page-shell"
import { DateRange } from "@/components/accounting/date-range"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Button } from "@/components/ui/button"
import { Table, TableBody, TableCell, TableHead, TableHeader, TableRow } from "@/components/ui/table"
import { FadeRow } from "@/components/motion/fade-row"
import { TableSkeleton } from "@/components/motion/table-skeleton"
import { useI18n } from "@/lib/i18n"
import { useChartAnimation, chartTooltipStyle } from "@/components/motion/chart-anim"
import { api, fmtMoney, todayStr, downloadCSV } from "@/lib/acct-client"

export default function ReportsPage() {
  const { t, locale } = useI18n()
  const anim = useChartAnimation()
  const [from, setFrom] = useState(`${new Date().getFullYear()}-01-01`)
  const [to, setTo] = useState(todayStr())
  const [d, setD] = useState<any>(null)
  const [err, setErr] = useState<string | null>(null)
  useEffect(() => {
    setErr(null)
    api("accounting/summary", { params: { from, to } }).then(setD).catch((e) => setErr(e.message))
  }, [from, to])

  const m = (n: any) => fmtMoney(n, locale)
  const pnlRows = d ? [
    { k: t("acct.pl.revenue"), v: d.pnl.revenue, b: true },
    { k: t("acct.pl.materials"), v: -d.pnl.materials },
    { k: t("acct.pl.labor"), v: -d.pnl.labor },
    ...d.pnl.expensesByCategory.map((e: any) => ({ k: `${t("acct.pl.expenses")} · ${t(`acct.cat.${e.category}`)}`, v: -e.total })),
    { k: t("acct.pl.net"), v: d.pnl.net, b: true },
  ] : []

  const exportAll = () => {
    if (!d) return
    const rows: any[] = [
      ...pnlRows.map((r) => ({ section: "P&L", item: r.k, amount: r.v })),
      { section: t("acct.rep.cash"), item: t("acct.cash.in"), amount: d.cash.in },
      { section: t("acct.rep.cash"), item: t("acct.cash.out"), amount: -d.cash.out },
      ...d.receivables.clients.filter((c: any) => c.balance > 0).map((c: any) => ({ section: t("acct.acc.receivables"), item: c.client, amount: c.balance })),
      ...d.payables.suppliers.filter((s: any) => s.balance > 0).map((s: any) => ({ section: t("acct.acc.payables"), item: s.name, amount: s.balance })),
      ...d.payroll.employees.filter((e: any) => e.owed_total > 0).map((e: any) => ({ section: t("acct.acc.payrollOwed"), item: e.name, amount: e.owed_total })),
    ]
    downloadCSV(`reporte-${from}-${to}.csv`, rows, [{ key: "section", label: t("acct.rep.section") }, { key: "item", label: t("acct.description") }, { key: "amount", label: t("acct.amount") }])
  }

  return (
    <PageShell title={t("acct.rep.title")} subtitle={t("acct.rep.subtitle")}
      actions={<>
        <Button variant="outline" onClick={() => window.print()}><Printer className="mr-2 h-4 w-4" />{t("acct.inv.print")}</Button>
        <Button variant="outline" onClick={exportAll} disabled={!d}><Download className="mr-2 h-4 w-4" />CSV</Button>
      </>}
    >
      <Card><CardContent className="pt-6"><DateRange from={from} to={to} onChange={(f, tt) => { setFrom(f); setTo(tt) }} /></CardContent></Card>
      {err && <p className="text-sm text-destructive">{err}</p>}
      {!d ? <TableSkeleton rows={6} /> : (<>
        <div className="grid grid-cols-2 gap-3 sm:gap-4 lg:grid-cols-4">
          <Stat title={t("acct.pl.revenue")} value={m(d.pnl.revenue)} icon={TrendingUp} />
          <Stat title={t("acct.pl.costs")} value={m(d.pnl.costs)} icon={TrendingDown} />
          <Stat title={t("acct.pl.net")} value={m(d.pnl.net)} tone={d.pnl.net >= 0 ? "good" : "bad"} hint={d.pnl.margin != null ? `${t("acct.pl.margin")} ${d.pnl.margin}%` : undefined} />
          <Stat title={t("acct.cash.net")} value={m(d.cash.net)} tone={d.cash.net >= 0 ? "good" : "bad"} icon={Wallet} hint={`${t("acct.cash.in")} ${m(d.cash.in)} · ${t("acct.cash.out")} ${m(d.cash.out)}`} />
        </div>

        <Card>
          <CardHeader><CardTitle className="text-base">{t("acct.rep.monthly")}</CardTitle></CardHeader>
          <CardContent>
            {d.monthly.length === 0 ? <Empty text={t("acct.noData")} /> : (
              <div className="h-72 w-full">
                <ResponsiveContainer width="100%" height="100%">
                  <BarChart data={d.monthly}>
                    <CartesianGrid strokeDasharray="3 3" stroke="var(--border)" />
                    <XAxis dataKey="month" tick={{ fill: "var(--muted-foreground)", fontSize: 12 }} stroke="var(--border)" />
                    <YAxis tick={{ fill: "var(--muted-foreground)", fontSize: 12 }} stroke="var(--border)" width={80} tickFormatter={(v) => fmtMoney(v, locale).replace(/\.00$/, "")} />
                    <Tooltip formatter={(v: any) => m(v)} contentStyle={chartTooltipStyle} cursor={{ fill: "var(--muted)" }} />
                    <Legend />
                    <Bar dataKey="revenue" name={t("acct.pl.revenue")} fill="var(--positive)" radius={[3, 3, 0, 0]} {...anim} />
                    <Bar dataKey="costs" name={t("acct.pl.costs")} fill="var(--negative)" radius={[3, 3, 0, 0]} {...anim} />
                    <Bar dataKey="profit" name={t("acct.pl.net")} fill="var(--chart-1)" radius={[3, 3, 0, 0]} {...anim} />
                  </BarChart>
                </ResponsiveContainer>
              </div>
            )}
          </CardContent>
        </Card>

        <div className="grid gap-4 lg:grid-cols-2">
          <Card>
            <CardHeader><CardTitle className="text-base">{t("acct.rep.pnl")}</CardTitle></CardHeader>
            <CardContent>
              <Table><TableBody>{pnlRows.map((r, i) => (
                <FadeRow index={i} key={i}><TableCell className={r.b ? "font-semibold" : "pl-6 text-muted-foreground"}>{r.k}</TableCell><TableCell className={`text-right tabular-nums ${r.b ? "font-semibold" : ""} ${r.v < 0 ? "text-negative" : ""}`}>{m(r.v)}</TableCell></FadeRow>
              ))}</TableBody></Table>
            </CardContent>
          </Card>
          <Card>
            <CardHeader><CardTitle className="text-base">{t("acct.rep.cash")}</CardTitle></CardHeader>
            <CardContent>
              <Table><TableBody>
                <TableRow><TableCell className="font-semibold">{t("acct.cash.in")}</TableCell><TableCell className="text-right tabular-nums font-semibold">{m(d.cash.in)}</TableCell></TableRow>
                <TableRow><TableCell className="pl-6 text-muted-foreground">{t("acct.cash.outExpenses")}</TableCell><TableCell className="text-right tabular-nums">{m(-d.cash.outExpenses)}</TableCell></TableRow>
                <TableRow><TableCell className="pl-6 text-muted-foreground">{t("acct.cash.outPurchases")}</TableCell><TableCell className="text-right tabular-nums">{m(-d.cash.outPurchases)}</TableCell></TableRow>
                <TableRow><TableCell className="pl-6 text-muted-foreground">{t("acct.cash.outSuppliers")}</TableCell><TableCell className="text-right tabular-nums">{m(-d.cash.outSuppliers)}</TableCell></TableRow>
                <TableRow><TableCell className="pl-6 text-muted-foreground">{t("acct.cash.outPayroll")}</TableCell><TableCell className="text-right tabular-nums">{m(-d.cash.outPayroll)}</TableCell></TableRow>
                <TableRow><TableCell className="font-semibold">{t("acct.cash.net")}</TableCell><TableCell className={`text-right tabular-nums font-semibold ${d.cash.net < 0 ? "text-negative" : "text-positive"}`}>{m(d.cash.net)}</TableCell></TableRow>
              </TableBody></Table>
            </CardContent>
          </Card>
        </div>

        <div className="grid gap-4 lg:grid-cols-3">
          <Card>
            <CardHeader><CardTitle className="text-base">{t("acct.rep.topDebtors")} · {m(d.receivables.total)}</CardTitle></CardHeader>
            <CardContent>{d.receivables.topDebtors.length === 0 ? <Empty text={t("acct.noData")} /> : (
              <Table><TableBody>{d.receivables.topDebtors.map((c: any, __i: number) => (
                <FadeRow index={__i} key={c.client}><TableCell>{c.client}{c.overLimit && <span className="ml-1 text-xs text-negative">({t("acct.acc.overLimit")})</span>}</TableCell><TableCell className="text-right tabular-nums">{m(c.balance)}</TableCell></FadeRow>
              ))}</TableBody></Table>
            )}</CardContent>
          </Card>
          <Card>
            <CardHeader><CardTitle className="text-base">{t("acct.acc.payables")} · {m(d.payables.total)}</CardTitle></CardHeader>
            <CardContent>{d.payables.suppliers.filter((s: any) => s.balance > 0).length === 0 ? <Empty text={t("acct.noData")} /> : (
              <Table><TableBody>{d.payables.suppliers.filter((s: any) => s.balance > 0).map((s: any, __i: number) => (
                <FadeRow index={__i} key={s.id}><TableCell>{s.name}</TableCell><TableCell className="text-right tabular-nums">{m(s.balance)}</TableCell></FadeRow>
              ))}</TableBody></Table>
            )}</CardContent>
          </Card>
          <Card>
            <CardHeader><CardTitle className="flex items-center gap-2 text-base"><Users className="h-4 w-4" />{t("acct.acc.payrollOwed")} · {m(d.payroll.owed)}</CardTitle></CardHeader>
            <CardContent>{d.payroll.employees.filter((e: any) => e.owed_total > 0).length === 0 ? <Empty text={t("acct.noData")} /> : (
              <Table>
                <TableHeader><TableRow><TableHead>{t("acct.employee")}</TableHead><TableHead className="text-right">{t("acct.att.days")}</TableHead><TableHead className="text-right">{t("acct.pay.owed")}</TableHead></TableRow></TableHeader>
                <TableBody>{d.payroll.employees.filter((e: any) => e.owed_total > 0).map((e: any, __i: number) => (
                  <FadeRow index={__i} key={e.id}><TableCell>{e.name}</TableCell><TableCell className="text-right tabular-nums">{e.days}</TableCell><TableCell className="text-right tabular-nums">{m(e.owed_total)}</TableCell></FadeRow>
                ))}</TableBody>
              </Table>
            )}</CardContent>
          </Card>
        </div>
      </>)}
    </PageShell>
  )
}
